for reg in 0 to (num_logical_regs - 1):
  if register_status_table[reg].valid:
    if register_status_table[reg].decay_ctr > 0:
      register_status_table[reg].decay_ctr = register_status_table[reg].decay_ctr - 1
    if register_status_table[reg].decay_ctr == 0:
      register_status_table[reg].valid = false

for reg in 0 to (num_logical_regs - 1):
  if not register_status_table[reg].valid and is_squashed(register_status_table[reg].payload):
    register_status_table[reg].payload = 0
